/// An 8-character share code from the alphabet `23456789ABCDEFGHJKMNPQRSTUVWXYZ` (31 symbols; no 0/O, 1/I/L).
///
/// 31⁸ ≈ 8.5 × 10¹¹ codes. Codes are generated by the app from an injected `RandomNumberGenerator`
/// (production: `SystemRandomNumberGenerator`) and registered with the share service, which rejects
/// collisions (docs/specs/SHARING.md). `rawValue` is always canonical (uppercase, 8 alphabet characters).
public struct ShortCode: Hashable, Sendable, Comparable, CustomStringConvertible, Codable {
    /// The code alphabet in ascending order.
    public static let alphabet = "23456789ABCDEFGHJKMNPQRSTUVWXYZ"
    /// Code length.
    public static let length = 8
    /// Longest input `normalize(_:)` looks at (generous room for spaces and dashes).
    public static let maxInputLength = 64

    static let alphabetBytes = Array(alphabet.utf8)
    private static let symbolCount = UInt64(alphabetBytes.count)
    /// Largest multiple of 31 that fits in `UInt64`: draws at or above it are rejected (no modulo bias).
    private static let rejectionLimit = UInt64.max - UInt64.max % symbolCount

    /// The canonical code, e.g. `"7KX2M9QH"`.
    public let rawValue: String

    /// Accepts only a canonical code (exactly 8 alphabet characters, uppercase). Use `normalize(_:)` for user input.
    public init?(_ rawValue: String) {
        let bytes = Array(rawValue.utf8)
        guard bytes.count == Self.length, bytes.allSatisfy({ Self.alphabetBytes.contains($0) }) else { return nil }
        self.rawValue = rawValue
    }

    private init(uncheckedBytes bytes: [UInt8]) {
        rawValue = String(decoding: bytes, as: UTF8.self)
    }

    /// Normalises user input: drops whitespace and dashes (ASCII `-`, U+2010…U+2015, U+2212), uppercases ASCII
    /// letters, then validates. Returns `nil` for anything that is not then a canonical code (wrong length,
    /// excluded characters such as `0 O 1 I L`, non-ASCII letters, input longer than `maxInputLength`).
    public static func normalize(_ input: String) -> ShortCode? {
        guard input.unicodeScalars.count <= maxInputLength else { return nil }
        var bytes: [UInt8] = []
        for scalar in input.unicodeScalars {
            if scalar.properties.isWhitespace || isDash(scalar) { continue }
            guard scalar.isASCII else { return nil }
            var byte = UInt8(scalar.value)
            if (UInt8(ascii: "a")...UInt8(ascii: "z")).contains(byte) { byte -= 32 }
            bytes.append(byte)
            if bytes.count > length { return nil }
        }
        return ShortCode(String(decoding: bytes, as: UTF8.self))
    }

    /// Like `normalize(_:)`, but throws `.invalidShortCode`.
    public static func parse(_ input: String) throws(ShareError) -> ShortCode {
        guard let code = normalize(input) else { throw .invalidShortCode }
        return code
    }

    /// A uniformly random code: each character is drawn by rejection sampling from 64-bit outputs of `rng`
    /// (draws ≥ the largest multiple of 31 are discarded), so every code has probability exactly 31⁻⁸.
    /// Deterministic for a deterministic generator, independent of the standard library's algorithms.
    public static func random<R: RandomNumberGenerator>(using rng: inout R) -> ShortCode {
        var bytes: [UInt8] = []
        bytes.reserveCapacity(length)
        while bytes.count < length {
            let draw = rng.next()
            guard draw < rejectionLimit else { continue }
            bytes.append(alphabetBytes[Int(draw % symbolCount)])
        }
        return ShortCode(uncheckedBytes: bytes)
    }

    /// Display form with a dash in the middle, e.g. `"7KX2-M9QH"` (`normalize` accepts it back).
    public var formatted: String {
        "\(rawValue.prefix(4))-\(rawValue.suffix(4))"
    }

    /// The canonical code.
    public var description: String { rawValue }

    public static func < (lhs: ShortCode, rhs: ShortCode) -> Bool { lhs.rawValue < rhs.rawValue }

    /// Decodes a canonical code string.
    public init(from decoder: any Decoder) throws {
        let container = try decoder.singleValueContainer()
        let raw = try container.decode(String.self)
        guard let code = ShortCode(raw) else {
            throw DecodingError.dataCorruptedError(in: container, debugDescription: "Invalid share code")
        }
        self = code
    }

    /// Encodes the canonical code string.
    public func encode(to encoder: any Encoder) throws {
        var container = encoder.singleValueContainer()
        try container.encode(rawValue)
    }

    private static func isDash(_ scalar: Unicode.Scalar) -> Bool {
        switch scalar.value {
        case 0x2D, 0x2010...0x2015, 0x2212: return true
        default: return false
        }
    }
}
